import json
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Look for exchange rate data
def search_json(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f"{path}.{k}" if path else k
            if 'exchange' in k.lower() or 'jpy' in k.lower() or 'yen' in k.lower():
                print(f"Found key: {new_path}")
            search_json(v, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_json(item, f"{path}[{i}]")

search_json(data)
